style.css:
@-moz-document domain("web.whatsapp.com") {
:root {
    color-scheme: dark !important;
    --bg-main: #0b0a0d;
    --bg-panel: #121015;
    --bg-input: #1b171d;
    --text-main: #f4edf4;
    --accent: #b9a1bd;
    --border-color: #302832;
  }

  html,
  body,
  #app,
  #app > div {
    background: var(--bg-main) !important;
    color: var(--text-main) !important;
  }

  /* Main panels */
  #side,
  #main,
  [data-testid="chat-list"],
  [data-testid="conversation-panel-wrapper"],
  [data-testid="conversation-panel-body"],
  [data-testid="chatlist-header"],
  [data-testid="conversation-header"] {
    background-color: var(--bg-panel) !important;
    color: var(--text-main) !important;
  }

  /* Headers and toolbars */
  header,
  footer,
  [role="banner"] {
    background-color: #100e12 !important;
    color: var(--text-main) !important;
    border-color: var(--border-color) !important;
  }

  /* Chat background */
  [data-testid="conversation-panel-body"] {
    background-color: #0b0a0d !important;
  }

  /* Message bubbles */
  .message-in .copyable-text,
  .message-in [data-testid="msg-container"] {
    background-color: #211c24 !important;
    color: #f4edf4 !important;
  }

  .message-out .copyable-text,
  .message-out [data-testid="msg-container"] {
    background-color: #39303e !important;
    color: #fff7ff !important;
  }

  /* Search and message inputs */
  input,
  textarea,
  [contenteditable="true"] {
    background-color: #1b171d !important;
    color: #f4edf4 !important;
    border-color: #39303e !important;
    caret-color: #d8bddc !important;
  }

  /* Chat list rows */
  [data-testid="cell-frame-container"],
  [role="listitem"] {
    border-color: #29232c !important;
  }

  [data-testid="cell-frame-container"]:hover {
    background-color: #211b25 !important;
  }

  /* Icons */
  svg {
    color: #c5b0ca;
  }

  /* Selection */
  ::selection {
    background: #755c7e !important;
    color: #ffffff !important;
  }

  /* Scrollbars */
  * {
    scrollbar-color: #514455 #100e12;
    scrollbar-width: thin;
  }

  /* Soft coquette details */
  button:hover,
  [role="button"]:hover {
    background-color: #29212e !important;
  }

  a {
    color: #d8bddc !important;
  }
}
